<html><head><script src="file:///app/bokehjs/build/js/bokeh.js"></script>
<script src="file:///app/bokehjs/build/js/bokeh-api.js"></script></head><body><div id="root"></div>
<script>
const P = Bokeh.Plotting
function fig(opts, ylim=[0,1], leg=null, legside="right") {
  const f = P.figure({width: 250, height: 250, ...opts})
  f.y_range = new Bokeh.Range1d({start: ylim[0], end: ylim[1]})
  const r = f.scatter({x:[0.1,0.9], y:[ylim[0]+0.1*(ylim[1]-ylim[0]), ylim[0]+0.9*(ylim[1]-ylim[0])]})
  if (leg) { const l = new Bokeh.Legend({items:[new Bokeh.LegendItem({label: leg, renderers:[r]})]}); f.add_layout(l, legside); f._leg=l }
  return f
}
const a = fig({title: "A title"}), b = fig({}), c = fig({}, [0,1]), d = fig({}, [1,2], "a"), e = fig({}, [0,1e9])
const row1 = new Bokeh.Row({children: [a,b,c,d,e]})
const c1 = fig({}, [0,1]), c2 = fig({}, [0,1e5]), c3 = fig({}, [0,1e9])
const col = new Bokeh.Column({children: [c1,c2,c3]})
const g1 = fig({title:"a"},[1,2],"a","left"), g2 = fig({},[0,1e6]), g3 = fig({width:500, x_axis_label:"time"},[1,2])
const grid = new Bokeh.GridBox({children: [[g1,0,0],[g2,0,1],[g3,1,0,1,2]]})
const r1 = fig({title:"right"},[1,2],"test","right"), r2 = fig({title:"left"},[1,2],"test","left"), r3=fig({title:"above"},[1,2],"test","above"), r4=fig({title:"below"},[1,2],"test","below")
const row2 = new Bokeh.Row({children:[r1,r2,r3,r4]})
const ff1 = fig({frame_width:200, frame_height:150},[0,1e6]), ff2 = fig({frame_width:200, frame_height:150, title:"t"},[1,2],"leg","right")
const row3 = new Bokeh.Row({children:[ff1, ff2]})
const all = new Bokeh.Column({children:[row1,row2,col,grid,row3]})
Bokeh.Plotting.show(all, "#root").then(()=>{window.ready=true})
window.step = (n) => {
  if (n==1) { c.y_range.end = 1e9; d._leg.items[0].label = {value: "a much longer key label"}; g2.y_range.end=1e9; ff1.y_range.end = 1e12; ff2._leg.items[0].label={value:"a much much longer legend label"} }
}
window.report = () => {
  const views = [...Bokeh.index.values()][0]
  const out = []
  for (const pv of views.owner.query(v => v.model instanceof Bokeh.Plot)) {
    const r = pv.el.getBoundingClientRect()
    const fr = pv.frame.bbox
    const issues=[]
    // check panels within plot
    for (const rv of pv.renderer_views.values()) {
      const lay = rv.layout; if (!lay || !rv.panel) continue
      const bb = lay.bbox
      const cs = lay._content_size ? lay._content_size() : null
      if (cs && (cs.width > bb.width+0.5 || cs.height > bb.height+0.5)) issues.push(`${rv.model.type}@${rv.panel.side} content ${cs.width}x${cs.height} > ${bb.width}x${bb.height}`)
      if (bb.left < -0.5 || bb.top < -0.5 || bb.right > r.width+0.5 || bb.bottom > r.height+0.5) issues.push(`${rv.model.type}@${rv.panel.side} out of plot ${JSON.stringify(bb.box)}`)
    }
    out.push({title: pv.model.title?.text, el: [r.left,r.top,r.width,r.height].map(Math.round), frame: [fr.left+r.left, fr.top+r.top, fr.width, fr.height].map(Math.round), issues})
  }
  return out
}
</script></body></html>
